import js from '@eslint/js';
import globals from 'globals';

/**
 * Flat ESLint config.
 *
 * `lib/client.js` is generated by `npm run build` (esbuild from `src/client/`),
 * so it is not linted directly — the sources under `src/client/` are.
 */
export default [
  {
    ignores: [
      'node_modules/**',
      'coverage/**',
      'lib/client.js',
      '.refs-*/**',
      '.tools/**',
    ],
  },
  js.configs.recommended,
  {
    languageOptions: {
      ecmaVersion: 2022,
      sourceType: 'module',
    },
    rules: {
      'no-unused-vars': [
        'error',
        {
          argsIgnorePattern: '^_',
          varsIgnorePattern: '^_',
          caughtErrors: 'none',
          ignoreRestSiblings: true,
        },
      ],
    },
  },
  {
    files: ['lib/**/*.js', 'scripts/**/*.mjs', 'test/**/*.mjs'],
    languageOptions: { globals: { ...globals.node } },
  },
  {
    files: ['src/client/**/*.js'],
    languageOptions: { globals: { ...globals.browser } },
  },
  {
    // These two modules intentionally strip control characters from user input,
    // so the control-character regex is the implementation, not a mistake.
    files: ['lib/parse.js', 'lib/store.js'],
    rules: { 'no-control-regex': 'off' },
  },
];
